# Test Suite for Checkout Component

Listen here, wanderer. In Bartertown, we build things that *work*. This checkout component? It's civilization. And civilization requires tests. Everybody knows the rules.

```typescript
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// Mock the contexts - I've built civilization. It's delicate.
const mockClearCart = vi.fn();
const mockProcessPayment = vi.fn();

vi.mock('./CartContext', () => ({
  useCart: () => ({
    items: [{ id: '1', name: 'Widget', price: 29.99 }],
    total: 29.99,
    clearCart: mockClearCart
  })
}));

vi.mock('./PaymentContext', () => ({
  usePayment: () => ({ processPayment: mockProcessPayment })
}));

describe('Checkout - This is Bartertown', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockProcessPayment.mockResolvedValue({ orderId: 'ORD-123' });
  });

  // HAPPY PATH - Two men enter, one man leaves with an order
  describe('Complete checkout flow', () => {
    it('navigates through all steps and places order successfully', async () => {
      const user = userEvent.setup();
      const onComplete = vi.fn();

      render(<Checkout onComplete={onComplete} />);

      // Shipping step
      await user.type(screen.getByLabelText(/street address/i), '123 Wasteland Ave');
      await user.type(screen.getByLabelText(/city/i), 'Bartertown');
      await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
      await user.type(screen.getByLabelText(/zip code/i), '90210');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Payment step
      await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
      await user.type(screen.getByLabelText(/expiry/i), '12/25');
      await user.type(screen.getByLabelText(/cvv/i), '123');
      await user.type(screen.getByLabelText(/name on card/i), 'Aunty Entity');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Review step
      expect(screen.getByText(/widget/i)).toBeInTheDocument();
      await user.click(screen.getByRole('button', { name: /place order/i }));

      // Confirmation
      await waitFor(() => {
        expect(screen.getByText(/order confirmed/i)).toBeInTheDocument();
        expect(screen.getByText('ORD-123')).toBeInTheDocument();
      });
      expect(onComplete).toHaveBeenCalledWith('ORD-123');
    });
  });

  // VALIDATION - Bust a deal, face the wheel
  describe('Form validation', () => {
    it('shows error for empty street address', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByRole('alert')).toHaveTextContent(/street address is required/i);
    });

    it('validates ZIP code format', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.type(screen.getByLabelText(/zip code/i), 'invalid');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
    });
  });

  // EDGE CASES - Who run Bartertown?
  describe('Empty cart handling', () => {
    it('displays empty cart message and continue shopping button', () => {
      vi.mocked(require('./CartContext').useCart).mockReturnValue({
        items: [], total: 0, clearCart: mockClearCart
      });
      const onCancel = vi.fn();

      render(<Checkout onCancel={onCancel} />);

      expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
    });
  });

  // ACCESSIBILITY - Breaking contracts has consequences
  describe('Accessibility', () => {
    it('has no accessibility violations', async () => {
      const { container } = render(<Checkout />);
      const results = await axe(container);
      expect(results).toHaveNoViolations();
    });
  });
});
